CircuitBreaker breaker =
        CircuitBreaker.ofDefaults("inventory-service");

Supplier<String> supplier =
        CircuitBreaker.decorateSupplier(
                breaker,
                () -> makeHttpCall(
                        "http://inventory-service/items/42")
        );

String response =
        Try.ofSupplier(supplier)
                .recover(ex -> "Fallback Response")
                .get();

